mapper.sql:
SELECT id, username, nickname, avatar_url, school, email, cf_handle, internal_solved, cf_solved, manual_solved, manual_declaration_count, total_score, `rank`, cf_verification_status, cf_data_source, cf_last_sync_at, manual_updated_at FROM ranked
WHERE id = #{userId}
ORDER BY total_score DESC, internal_solved DESC, id ASC
